class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = "ValidationError";   // shows up in stack traces and logs
    this.field = field;
  }
}

function parseAge(input) {
  const age = Number(input);
  if (!Number.isInteger(age) || age < 0) {
    throw new ValidationError("age must be a whole number", "age");
  }
  return age;
}

try {
  parseAge("abc");
} catch (error) {
  if (error instanceof ValidationError) {
    console.log(error.field, error.message); // age age must be a whole number
  } else {
    throw error;                              // not ours: let it propagate
  }
}

async function loadSettings(path) {
  try {
    return JSON.parse(await readFile(path, "utf8"));
  } catch (error) {
    throw new Error(`could not load settings from ${path}`, { cause: error });
  }
}

// later, in a top-level handler:
// error.message        -> "could not load settings from app.json"
// error.cause.message  -> "Unexpected token } in JSON at position 42"

function tryParseAge(input) {
  try {
    return { ok: true, value: parseAge(input) };
  } catch (error) {
    if (error instanceof ValidationError) {
      return { ok: false, error: { field: error.field, message: error.message } };
    }
    throw error;   // a bug, not bad input: still an exception
  }
}

const results = ["42", "-1"].map(tryParseAge);
